<?php
namespace App\Filament\Resources;
use App\Filament\Resources\DiscordBotResource\Pages; use App\Models\DiscordBot; use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table;
class DiscordBotResource extends Resource { protected static ?string $model=DiscordBot::class; protected static ?string $navigationIcon='heroicon-o-cpu-chip'; protected static ?string $navigationLabel='Bots Discord';
 public static function form(Form $form): Form{return $form->schema([Forms\Components\TextInput::make('name')->required()->maxLength(255),Forms\Components\TextInput::make('client_id')->required()->unique(ignoreRecord:true),Forms\Components\TextInput::make('token')->password()->revealable()->required(fn(string $operation):bool=>$operation==='create')->dehydrated(fn(?string $state):bool=>filled($state))->helperText('Le token est chiffré et ne sera plus affiché.'),Forms\Components\Toggle::make('is_active'),Forms\Components\KeyValue::make('default_config')]);}
 public static function table(Table $table): Table{return $table->columns([Tables\Columns\TextColumn::make('name')->searchable(),Tables\Columns\TextColumn::make('client_id')->copyable(),Tables\Columns\IconColumn::make('is_active')->boolean(),Tables\Columns\TextColumn::make('connection_status')->badge()->color(fn(string $state):string=>match($state){'online'=>'success','error'=>'danger',default=>'gray'}),Tables\Columns\TextColumn::make('last_connected_at')->dateTime()])->actions([Tables\Actions\EditAction::make()]);}
 public static function getPages():array{return ['index'=>Pages\ListDiscordBots::route('/'),'create'=>Pages\CreateDiscordBot::route('/create'),'edit'=>Pages\EditDiscordBot::route('/{record}/edit')];}}
